from sklearn.metrics import roc_auc_score


# Define the CNN model
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species=206, dropout_rate=0.5, conv_layers=3):
        super(BirdCLEFModel, self).__init__()
        self.conv_layers = nn.Sequential()
        
        # Convolutional layers with batch normalization and ReLU activation
        in_channels = 1
        for i in range(conv_layers):
            out_channels = 32 * (i + 1)
            self.conv_layers.add_module(f'conv{i+1}', nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            self.conv_layers.add_module(f'bn{i+1}', nn.BatchNorm2d(out_channels))
            self.conv_layers.add_module(f'relu{i+1}', nn.ReLU())
            in_channels = out_channels
        
        # Adaptive average pooling for robust flattening
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        
        # Classifier with dropout and linear layers
        self.classifier = nn.Sequential(
            nn.Linear(out_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Hyperparameters
NUM_EPOCHS = 20
BATCH_SIZE = 32
LEARNING_RATE = 0.001
DROPOUT_RATE = 0.5
CONV_LAYERS = 3

# Data loaders
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=BATCH_SIZE,
    augment=True,      # Enable augmentation for training
    val_split=0.2,     # 80/20 split
)

# Model, criterion, and optimizer
model = BirdCLEFModel(num_species=206, dropout_rate=DROPOUT_RATE, conv_layers=CONV_LAYERS).to('cuda')
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=1e-4)

# Training loop
train_losses = []
for epoch in range(NUM_EPOCHS):
    model.train()
    for batch_idx, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        try:
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
            loss.backward()
            optimizer.step()
            
            train_losses.append(loss.item())
            if batch_idx % 10 == 0:
                print(f'Epoch [{epoch+1}/{NUM_EPOCHS}], Batch [{batch_idx+1}/{len(train_loader)}], Loss: {loss.item():.4f}')
        
        except RuntimeError as e:
            if 'out of memory' in str(e):
                torch.cuda.empty_cache()
                BATCH_SIZE //= 2
                print(f"Reducing batch size to {BATCH_SIZE}")
                continue
        
        finally:
            torch.cuda.empty_cache()

# Evaluation on validation set
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in val_loader:
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        outputs = model(inputs)
        all_preds.extend(outputs.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())

final_auc = roc_auc_score(all_labels, all_preds, average='weighted')

# Save metrics and model
metrics = {
    "final_train_loss": sum(train_losses) / len(train_losses),
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": NUM_EPOCHS,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print(f"METRICS: {json.dumps(metrics)}")

torch.save(model.state_dict(), 'model.pt')